/// The WSM (weapon speed modifier) of `code`, or `None` if it is no weapon row.
#[must_use]
pub fn wsm(code: &str) -> Option<i32> {
    WEAPONS
        .binary_search_by(|(c, _, _, _, _, _)| c.cmp(&code))
        .ok()
        .and_then(|i| WEAPONS.get(i))
        .map(|&(_, wsm, _, _, _, _)| wsm)
}

/// The required character level of `code`'s weapon row, `None` if unknown.
#[must_use]
pub fn level(code: &str) -> Option<u32> {
    WEAPONS
        .binary_search_by(|(c, _, _, _, _, _)| c.cmp(&code))
        .ok()
        .and_then(|i| WEAPONS.get(i))
        .map(|&(_, _, _, lvl, _, _)| lvl)
}

/// Whether `code`'s weapon row is two-handed, `None` if the code is no weapon row.
#[must_use]
pub fn two_handed(code: &str) -> Option<bool> {
    WEAPONS
        .binary_search_by(|(c, _, _, _, _, _)| c.cmp(&code))
        .ok()
        .and_then(|i| WEAPONS.get(i))
        .map(|&(_, _, _, _, two_handed, _)| two_handed)
}

/// The display name of `code`'s weapon row, `None` if unknown.
#[must_use]
pub fn name(code: &str) -> Option<&'static str> {
    WEAPONS
        .binary_search_by(|(c, _, _, _, _, _)| c.cmp(&code))
        .ok()
        .and_then(|i| WEAPONS.get(i))
        .map(|&(_, _, _, _, _, name)| name)
}
